const RULES={
"Basics":[
 ["The match","Each team has up to 11 players on the pitch, including one goalkeeper. Two halves of 45 minutes, plus added time."],
 ["How a goal counts","The whole ball must cross the goal line between the posts and under the crossbar."],
 ["Substitutions","In most top competitions a team can make up to five substitutions, in no more than three stops during play (half-time does not count)."],
 ["Win, draw, lose","In a league, a win is worth 3 points, a draw 1 and a loss 0. In a knockout cup, level games go to extra time or penalties."]],
"Restarts":[
 ["Throw-in","When the ball fully crosses a sideline, the team that did not touch it last throws it in with both hands from behind the head."],
 ["Corner kick or goal kick?","Ball over the goal line (outside the goal): defender touched it last means a corner; attacker touched it last means a goal kick."],
 ["Direct and indirect free kicks","A direct free kick can be shot straight into goal; an indirect one must touch another player first. Opponents stand at least 9.15 m away."],
 ["Penalty kick","For a foul by a defender in their own penalty area. Taken from 11 m with only the goalkeeper to beat."]],
"Fouls & play":[
 ["Fouls","A challenge that is careless, reckless or uses excessive force, such as tripping, pushing or kicking."],
 ["Handball","It is an offence to deliberately handle the ball or make your body bigger with your arm. The arm starts at the bottom of the armpit."],
 ["Advantage","If the fouled team still has a good attack, the referee lets play continue. A card can still be shown later."]],
"Tech & tournaments":[
 ["VAR","The Video Assistant Referee reviews goals, penalties, direct red cards and mistaken identity. The referee still makes the final call."],
 ["Goal-line technology","Cameras tell the referee's watch within a second when the whole ball has crossed the line."],
 ["Goalkeeper 8-second rule","Since 2025, a goalkeeper who holds the ball for more than eight seconds gives the other team a corner kick.",true],
 ["Extra time and penalties","Knockout games level after 90 minutes get two extra halves of 15 minutes, then a penalty shootout."]]};

const GLOSSARY=[
["Assist","The pass that sets up a goal."],["Brace","Two goals by one player in a match."],["Hat-trick","Three goals by one player in a match."],["Clean sheet","When a team concedes no goals in a match."],["Nil","Zero. A 2–0 score is said “two-nil”."],["Derby","A match between two rivals from the same city or region."],["Nutmeg","Passing the ball through an opponent's legs."],["Own goal","When a player accidentally scores in their own net."],["Set piece","A planned move from a dead ball: corner, free kick or throw-in."],["Cross","A pass from the side of the pitch into the area in front of goal."],["Through ball","A pass into the space behind the defenders."],["One-two","A quick pass to a teammate who passes straight back."],["Counter-attack","Attacking at speed right after winning the ball."],["Pressing","Chasing opponents to win the ball back quickly."],["Parking the bus","Defending with almost everyone behind the ball."],["Tiki-taka","Short, quick passing made famous by Barcelona and Spain."],["False nine","A striker who drops back into midfield."],["Volley","Kicking the ball before it touches the ground."],["Bicycle kick","An overhead kick with the player in the air, back to goal."],["Panenka","A penalty chipped softly down the middle, named after Antonín Panenka (1976)."],["Stoppage time","Minutes added at the end of each half. Also called added time."],["Bench","The substitutes and coaches at the side of the pitch."],["Captain's armband","Worn by the team captain, who leads the team."],["Man of the match","The best player in the game."],["The double","Winning the league and the main domestic cup in one season."],["Treble","Three major trophies in one season, usually league, cup and Champions League."],["Relegation","Dropping down to a lower division after finishing near the bottom."],["Promotion","Moving up a division after finishing near the top."],["Transfer window","The periods when clubs may buy and sell players."],["xG (expected goals)","A statistic that rates how likely a shot was to be a goal, from 0 to 1."],["Golden Boot","The award for the top scorer in a tournament or league."],["Woodwork","The posts and crossbar. “Hitting the woodwork” means hitting the frame of the goal."]];

